// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v));
        require(success, "transfer reverted");
        bool result = abi.decode(data, (bool));
        assertTrue(result);
    }
}

